def roll(self, pins):
    if self.game_over:
        raise Exception("Cannot roll after the game is over")
    if not 0 <= pins <= 10:
        raise Exception("Roll must be between 0 and 10")
    first = self.current[0] if self.current else None
    if len(self.frames) < 9:
        if self.current and len(self.current) == 1:
            if first + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
    else:
        # 10th frame
        if len(self.current) == 2:
            if first == 10 and self.current[1] != 10 and self.current[1] + pins > 10:
                raise Exception("Bonus rolls after a strike cannot score more than 10 points")
        elif len(self.current) == 1:
            if first != 10 and first + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
    self.rolls.append(pins)
    self.current.append(pins)
    self._maybe_close_frame()
```

